 out={'checks':{k:bool(v) for k,v in checks.items()},'all_required_checks_pass':bool(all(checks.values())),'figure_exports':exports,'visual_review_complete':False,'visual_review_panels':[],'nature_source_validator_exceptions':{'PDF':'Explicit user policy; SVG used for editable text and glyph audit','TIFF_600dpi':'Predeclared SVG+300dpiPNG contract; no submission TIFF requested','width_heuristic':'Actual exported SVG width verified at183mm','DEMO_DATA':'Random generator occurs only in verification of declared balanced draws; no synthetic plotting data.','UNCERTAINTY_ENCODING':'I1/I2 draw exact stored95%CI endpoints manually; I3/I4 show deterministic per-donor observations, not aggregate uncertainties.'}}
