def report():
 assert not P.exists(),'Inspect and preserve existing report before updates'
 v=json.loads((O/'verdict.json').read_text());qa=json.loads((O/'verification.json').read_text());assert qa['all_required_checks_pass'] and qa['visual_review_complete']
 a=read('inference_agreement_matrix.tsv');dirc=read('effect_direction_consensus.tsv');con=read('effect_inference_consensus.tsv');tc=read('target_inference_classification.tsv');jk=read('jackknife_summary.tsv');bc=read('bca_feasibility.tsv');tests=read('donor_sign_wilcoxon_results.tsv');equal=read('donor_equal_effect_summary.tsv')
 def targetfield(target):return '; '.join(f'{r.effect}: {r.direction_consensus}' for r in dirc[dirc.target.eq(target)].itertuples())
